using System.Text.Json;using JobOrbit.Application.DTOs.AdminUsers;using JobOrbit.Application.DTOs.Jobs;using JobOrbit.Application.Interfaces;using JobOrbit.Domain.Entities;using JobOrbit.Domain.Enums;using Microsoft.EntityFrameworkCore;
namespace JobOrbit.Infrastructure.Persistence.Repositories;public sealed class AdminUserRepository(JobOrbitDbContext db):IAdminUserRepository
{static string?Clean(string?v)=>string.IsNullOrWhiteSpace(v)?null:v.Trim();IQueryable<User>Users()=>db.Users;
public async Task<PagedResultDto<AdminUserListItemDto>>ListAsync(AdminUserQuery q,UserRole?role,bool?active,CancellationToken t=default){var users=Users().AsNoTracking();if(role.HasValue)users=users.Where(x=>x.Role==role);if(active.HasValue)users=users.Where(x=>x.IsActive==active);if(q.OrganizationId.HasValue)users=users.Where(x=>(x.RecruiterProfile!=null&&x.RecruiterProfile.OrganizationId==q.OrganizationId)||(x.HiringManagerProfile!=null&&x.HiringManagerProfile.OrganizationId==q.OrganizationId));if(q.DepartmentId.HasValue)users=users.Where(x=>x.HiringManagerProfile!=null&&x.HiringManagerProfile.DepartmentId==q.DepartmentId);if(!string.IsNullOrWhiteSpace(q.Search)){var s=q.Search.Trim();users=users.Where(x=>x.FirstName.Contains(s)||x.LastName.Contains(s)||(x.FirstName+" "+x.LastName).Contains(s)||x.Email.Contains(s));}users=q.Sort.ToLowerInvariant()switch{"oldest"=>users.OrderBy(x=>x.CreatedAt),"name"=>users.OrderBy(x=>x.FirstName).ThenBy(x=>x.LastName),_=>users.OrderByDescending(x=>x.CreatedAt)};var total=await users.CountAsync(t);var items=await users.Skip((q.Page-1)*q.PageSize).Take(q.PageSize).Select(x=>new AdminUserListItemDto{UserId=x.Id,FullName=x.FirstName+" "+x.LastName,Email=x.Email,Role=x.Role==UserRole.Administrator?"Admin":x.Role.ToString(),Status=x.IsActive?"Active":"Inactive",OrganizationName=x.RecruiterProfile!=null?x.RecruiterProfile.Organization.Name:x.HiringManagerProfile!=null?x.HiringManagerProfile.Organization.Name:null,DepartmentName=x.HiringManagerProfile!=null&&x.HiringManagerProfile.Department!=null?x.HiringManagerProfile.Department.Name:null,CreatedAt=x.CreatedAt}).ToListAsync(t);return new(){Items=items,Page=q.Page,PageSize=q.PageSize,TotalItems=total,TotalPages=(int)Math.Ceiling(total/(double)q.PageSize)};}
public Task<AdminUserDetailsDto?>DetailsAsync(int id,CancellationToken t=default)=>Users().AsNoTracking().Where(x=>x.Id==id).Select(x=>new AdminUserDetailsDto{UserId=x.Id,FirstName=x.FirstName,LastName=x.LastName,FullName=x.FirstName+" "+x.LastName,Email=x.Email,Phone=x.CandidateProfile!=null?x.CandidateProfile.PhoneNumber:x.RecruiterProfile!=null?x.RecruiterProfile.PhoneNumber:x.HiringManagerProfile!=null?x.HiringManagerProfile.PhoneNumber:null,Role=x.Role==UserRole.Administrator?"Admin":x.Role.ToString(),Status=x.IsActive?"Active":"Inactive",OrganizationId=x.RecruiterProfile!=null?x.RecruiterProfile.OrganizationId:x.HiringManagerProfile!=null?x.HiringManagerProfile.OrganizationId:null,OrganizationName=x.RecruiterProfile!=null?x.RecruiterProfile.Organization.Name:x.HiringManagerProfile!=null?x.HiringManagerProfile.Organization.Name:null,DepartmentId=x.HiringManagerProfile!=null?x.HiringManagerProfile.DepartmentId:null,DepartmentName=x.HiringManagerProfile!=null&&x.HiringManagerProfile.Department!=null?x.HiringManagerProfile.Department.Name:null,CreatedAt=x.CreatedAt,UpdatedAt=x.UpdatedAt,ProfessionalTitle=x.CandidateProfile!=null?x.CandidateProfile.Headline:null,Education=x.CandidateProfile!=null?x.CandidateProfile.Education:null,Skills=x.CandidateProfile==null?new List<string>():x.CandidateProfile.CandidateSkills.Select(s=>s.Skill.Name).ToList(),JobTitle=x.RecruiterProfile!=null?x.RecruiterProfile.JobTitle:x.HiringManagerProfile!=null?x.HiringManagerProfile.JobTitle:null}).SingleOrDefaultAsync(t);
async Task<bool>Org(int?org,CancellationToken t)=>org.HasValue&&await db.Organizations.AnyAsync(x=>x.Id==org&&x.IsActive,t);async Task<bool>Dept(int?dept,int?org,CancellationToken t)=>!dept.HasValue||await db.Departments.AnyAsync(x=>x.Id==dept&&x.OrganizationId==org&&x.IsActive,t);
public async Task<AdminUserMutationResult>CreateAsync(int admin,CreateAdminUserRequest r,UserRole role,string hash,CancellationToken t=default){var email=r.Email.Trim().ToLowerInvariant();if(await db.Users.AnyAsync(x=>x.Email.ToLower()==email,t))return new(AdminUserMutationOutcome.DuplicateEmail);if(role is UserRole.Recruiter or UserRole.HiringManager&&!await Org(r.OrganizationId,t))return new(AdminUserMutationOutcome.InvalidOrganization);if(role==UserRole.HiringManager&&!await Dept(r.DepartmentId,r.OrganizationId,t))return new(AdminUserMutationOutcome.InvalidDepartment);await using var tx=db.Database.IsRelational()?await db.Database.BeginTransactionAsync(t):null;var user=new User{FirstName=r.FirstName.Trim(),LastName=r.LastName.Trim(),Email=email,PasswordHash=hash,Role=role,IsActive=r.IsActive};db.Users.Add(user);await db.SaveChangesAsync(t);var phone=Clean(r.Phone);if(role==UserRole.Candidate)db.CandidateProfiles.Add(new(){UserId=user.Id,PhoneNumber=phone});else if(role==UserRole.Recruiter)db.RecruiterProfiles.Add(new(){UserId=user.Id,OrganizationId=r.OrganizationId!.Value,JobTitle="Recruiter",PhoneNumber=phone});else if(role==UserRole.HiringManager)db.HiringManagerProfiles.Add(new(){UserId=user.Id,OrganizationId=r.OrganizationId!.Value,DepartmentId=r.DepartmentId,JobTitle="Hiring Manager",PhoneNumber=phone});db.AuditLogs.Add(new(){UserId=admin,EntityName=nameof(User),EntityId=user.Id,Action="AdminCreateUser",NewValues=JsonSerializer.Serialize(new{user.Email,Role=role.ToString(),user.IsActive})});await db.SaveChangesAsync(t);if(tx is not null)await tx.CommitAsync(t);return new(AdminUserMutationOutcome.Success,await DetailsAsync(user.Id,t));}
public async Task<AdminUserMutationResult>UpdateAsync(int admin,int id,UpdateAdminUserRequest r,UserRole role,CancellationToken t=default){var user=await Users().Include(x=>x.CandidateProfile).Include(x=>x.RecruiterProfile).Include(x=>x.HiringManagerProfile).SingleOrDefaultAsync(x=>x.Id==id,t);if(user is null)return new(AdminUserMutationOutcome.NotFound);if(user.Role!=role)return new(AdminUserMutationOutcome.DangerousRoleChange);if(role is UserRole.Recruiter or UserRole.HiringManager&&!await Org(r.OrganizationId,t))return new(AdminUserMutationOutcome.InvalidOrganization);if(role==UserRole.HiringManager&&!await Dept(r.DepartmentId,r.OrganizationId,t))return new(AdminUserMutationOutcome.InvalidDepartment);user.FirstName=r.FirstName.Trim();user.LastName=r.LastName.Trim();var phone=Clean(r.Phone);if(user.CandidateProfile!=null)user.CandidateProfile.PhoneNumber=phone;if(user.RecruiterProfile!=null){user.RecruiterProfile.PhoneNumber=phone;user.RecruiterProfile.OrganizationId=r.OrganizationId!.Value;}if(user.HiringManagerProfile!=null){user.HiringManagerProfile.PhoneNumber=phone;user.HiringManagerProfile.OrganizationId=r.OrganizationId!.Value;user.HiringManagerProfile.DepartmentId=r.DepartmentId;}db.AuditLogs.Add(new(){UserId=admin,EntityName=nameof(User),EntityId=id,Action="AdminUpdateUser"});await db.SaveChangesAsync(t);return new(AdminUserMutationOutcome.Success,await DetailsAsync(id,t));}
public async Task<AdminUserMutationResult>StatusAsync(int admin,int id,UpdateUserStatusRequest r,CancellationToken t=default){if(admin==id)return new(AdminUserMutationOutcome.SelfStatusChange);var user=await db.Users.SingleOrDefaultAsync(x=>x.Id==id,t);if(user is null)return new(AdminUserMutationOutcome.NotFound);if(!r.IsActive&&user.Role==UserRole.Administrator&&await db.Users.CountAsync(x=>x.Role==UserRole.Administrator&&x.IsActive,t)<=1)return new(AdminUserMutationOutcome.LastActiveAdmin);user.IsActive=r.IsActive;db.AuditLogs.Add(new(){UserId=admin,EntityName=nameof(User),EntityId=id,Action=r.IsActive?"AdminActivateUser":"AdminDeactivateUser",NewValues=JsonSerializer.Serialize(new{r.IsActive,Reason=Clean(r.Reason)})});await db.SaveChangesAsync(t);return new(AdminUserMutationOutcome.Success,await DetailsAsync(id,t));}
public async Task<AdminUserMutationOutcome>ResetPasswordAsync(int admin,int id,string hash,CancellationToken t=default){var user=await db.Users.SingleOrDefaultAsync(x=>x.Id==id,t);if(user is null)return AdminUserMutationOutcome.NotFound;user.PasswordHash=hash;db.AuditLogs.Add(new(){UserId=admin,EntityName=nameof(User),EntityId=id,Action="AdminResetPassword"});await db.SaveChangesAsync(t);return AdminUserMutationOutcome.Success;}public Task<User?>UserForPasswordAsync(int id,CancellationToken t=default)=>db.Users.SingleOrDefaultAsync(x=>x.Id==id,t);}
